import {combustionProducts} from './combustion-products.js';
import {mountCombustion,shelfTarget} from './combustion-workbench.js';
import {mountActivity} from './activity-ladder.js';
import {metals,nonmetals} from './model.js';
import {sampleVisual} from './specimens.js';
import {bindDrop} from './direct-manipulation.js';
import {materialCases} from './journey-cards.js';
import {bottleSolutions} from './bottle-ph-state.js';
// Keep the historical :ph evidence key for completed saved bottle observations.
export function sampleIcon(key){return sampleVisual(key==='CO'?'C':key,false,true,'tray-'+key,{form:{Mg:'ribbon',Cu:'sheet',Zn:'powder',Na:'block',S:'powder',P:'powder'}[key]});}
export function mountBurn(root,c,ctx){
 const {s,has,record,notice,delay}=ctx,key=s.selected,isMetal=!!metals[key],d=isMetal?metals[key]:nonmetals[key];
 let localBurned=false,localCool=true,running=false,localPoint=null;const burned=()=>localBurned,cooled=()=>localCool;
 root.innerHTML=`<div class="combustion-studio integrated-studio" aria-label="樣本架與燃燒實驗台" id="combustion-studio" tabindex="-1"><div class="specimen-shelf"></div><div class="bench-workspace"><div class="bench-sequence"><span>取樣與燃燒</span><i>→</i><span>產物入水</span><i>→</i><span>酸鹼性比較</span></div><p class="experiment-purpose" data-stage-purpose></p><div class="burn-content"></div></div></div><div class="comparison-sheet"></div><div class="activity-mount"></div>`;
 const content=root.querySelector('.burn-content'),sheet=root.querySelector('.comparison-sheet');
 function table(){sheet.innerHTML=`<table><caption>你的觀察表 · 燃燒／加熱的產物與反應式</caption><thead><tr><th>樣本</th><th>燃燒後／冷卻後</th><th>產物與化學反應式</th><th>遇水後的比較</th></tr></thead><tbody>${materialCases[c.type].map(([k,name])=>{const m=metals[k]||nonmetals[k],metalCase=!!metals[k];return `<tr><th>${name}</th><td>${has(k+':burn')?metalCase?{Cu:'表面變黑',Mg:'白色固體',Zn:'白色氧化鋅（冷卻後）',Na:'氧充足：淡黃色產物'}[k]:{S:'無色氣體',P:'白色固體微粒',C:'CO₂：無色氣體',CO:'可能有 CO；實際可混合'}[k]:'尚未觀察'}</td><td class="combustion-product-record"><b>${combustionProducts[k].product}</b><span class="combustion-record-equation">${combustionProducts[k].equation}</span><small>${combustionProducts[k].note}</small></td><td>${bottleSolutions[k]?(has(k+':ph')?bottleSolutions[k]==='acid'?'藍→紅；紅不變':'紅、藍皆無明顯變色':'尚未測試'):has(k+':wet')?m.litmus==='base'?'紅→藍；藍不變':m.litmus==='acid'?'藍→紅；紅不變':'紅、藍皆無明顯變色':'尚未測試'}</td></tr>`;}).join('')}</tbody></table>`;if(c.type==='combustion'||isMetal)mountActivity(root.querySelector('.activity-mount'),ctx);}
 function renderBurn(replay=false){root.querySelector('[data-stage-purpose]').textContent='在同一台追蹤：燃燒 → 產物遇水 → 石蕊試紙觀察酸鹼性。';if(replay){localBurned=false;localCool=true;}s.tab='burn';content.innerHTML='<div data-combustion-mount></div>';mountCombustion(content.querySelector('[data-combustion-mount]'),{key,isMetal,autoLoad:!!s.autoLoad,spoonOrigin:burned()?localPoint:s.spoonOrigin,onCleanup:ctx.onCleanup,completed:burned()&&!replay,cool:cooled(),token:sampleIcon(key),name:d.name,delay,notice,onStart:()=>{running=true;},onComplete:point=>{localPoint=point;running=false;localBurned=true;record(key+':burn');if(key==='Zn')record('Zn:cool');renderBurn();table();},onCool:()=>{localPoint=[400,335];localCool=true;record('Zn:cool');renderBurn();table();},onWetComplete:()=>{record(key+(bottleSolutions[key]?':ph':':wet'));table();}});s.autoLoad=false;s.spoonOrigin=null;renderShelf();}
 function renderShelf(){const shelf=root.querySelector('.specimen-shelf');shelf.hidden=false;if(c.type!=='combustion'){shelf.hidden=true;return;}shelf.innerHTML='<div class="shelf-heading"><b>鐵匠的樣本架</b><span>抓取樣本 → 放上燃燒匙</span></div>'+[['metals','金屬','metals'],['nonmetals','非金屬','nonmetals']].map(([type,title,group])=>'<section class="specimen-group '+group+'" aria-label="'+title+'樣本"><h4>'+title+'<small>'+ (group==='metals'?'銅・鎂・鋅・鈉':'硫・紅磷・碳')+'</small></h4><div class="shelf-rail">'+materialCases[type].map(([k,label])=>'<div class="shelf-specimen '+(key===k?'selected':'')+'" data-shelf-sample="'+k+'" aria-label="'+label+'樣本"><div class="specimen-vial">'+sampleIcon(k)+'</div><b>'+label+'</b><small>'+ (has(k+':burn')?'✓ 已觀察':'拖曳取用')+'</small></div>').join('')+'</div></section>').join('');for(const item of shelf.querySelectorAll('[data-shelf-sample]'))bindDrop(item,()=>shelfTarget(root.querySelector('.combustion-workbench')),{onDrop:()=>{const target=shelfTarget(root.querySelector('.combustion-workbench'));ctx.setCase(item.dataset.shelfSample,true,[Number(target.dataset.spoonX),Number(target.dataset.spoonY)]);},onMiss:()=>notice('對準眼前燃燒匙的凹槽，匙口亮起後再放開；不用回到最初的位置。')});}

 renderBurn();table();
}
